'use strict';
// Weekly labels follow the supplied Week 7–14 lecture notes, not manuscript chapters.
const SECOND_HALF_TOPICS=SECOND_HALF_WEEKS.map(w=>({id:'week'+w.week,name:'Week '+w.week+' · '+w.name,icon:'W'+w.week,tip:w.description}));
let halfWeek='all',halfMode='all',halfProgress='all',halfSearch='',halfPage=0;
function halfFiltered(){const needle=halfSearch.trim().toLowerCase();return SECOND_HALF_MCQS.filter(q=>(halfWeek==='all'||q.week===Number(halfWeek))&&(halfMode==='all'||q.mode===halfMode)&&(halfProgress==='all'||(halfProgress==='new'?!state.records[q.id]:halfProgress==='missed'?state.records[q.id]&&!state.records[q.id].latestCorrect:state.records[q.id]?.latestCorrect))&&(!needle||[q.id,q.title,q.code,SECOND_HALF_WEEKS.find(w=>w.week===q.week).name].join(' ').toLowerCase().includes(needle)));}
function renderHalfList(){const qs=halfFiltered(),size=20;halfPage=Math.min(halfPage,Math.max(0,Math.ceil(qs.length/size)-1));document.getElementById('half-count').textContent=qs.length+' matching questions';document.getElementById('half-list').innerHTML=qs.slice(halfPage*size,(halfPage+1)*size).map(q=>`<button class="exercise-card" data-half-question="${q.id}"><span class="tag">Week ${q.week} · ${q.mode==='python-output'?'Code trace':'Concept'}</span><h3>${esc(q.title)}</h3><span class="card-bottom"><span>${state.records[q.id]?.latestCorrect?'✓ Correct':state.records[q.id]?'Revisit':'Not attempted'}</span><span aria-hidden="true">→</span></span></button>`).join('')||'<p class="empty">No questions match. Try changing the filters.</p>';document.getElementById('half-pagination').innerHTML=qs.length>size?`<div class="actions"><button class="secondary" data-half-page="${halfPage-1}" ${halfPage===0?'disabled':''}>← Previous</button><span class="muted">Page ${halfPage+1} of ${Math.ceil(qs.length/size)}</span><button class="secondary" data-half-page="${halfPage+1}" ${(halfPage+1)*size>=qs.length?'disabled':''}>Next →</button></div>`:'';}
function secondHalfHome(){const attempted=SECOND_HALF_MCQS.filter(q=>state.records[q.id]).length,correct=SECOND_HALF_MCQS.filter(q=>state.records[q.id]?.latestCorrect).length;paint(`${practiceTabs('second')}<div class="intro"><span class="eyebrow">PRACTICE SETS · WEEKS 7–14</span><h1>Build on your foundations.</h1><p>400 original MCQs with explanations: 50 per week, including 200 Python output questions and 200 conceptual questions. Follow the weekly lecture-note sequence, from testing to integrated course review.</p><p class="muted">${attempted} / 400 attempted · ${correct} currently correct · Instructor: Prof. Yanwei Wang</p><div class="actions"><button class="primary" data-half-start="mixed">24-question mixed round →</button><button class="secondary" data-half-start="missed">Revisit second-half mistakes</button></div><p class="code-info">A mixed round samples three questions from each week. Each snippet starts fresh. Python 3 output is checked in advance; assertions are enabled. Cross-language questions state the language. These are formative practice questions.</p></div><div class="bank-grid">${SECOND_HALF_WEEKS.map(w=>{const qs=SECOND_HALF_MCQS.filter(q=>q.week===w.week),n=qs.filter(q=>state.records[q.id]).length;return `<section class="panel bank-card"><span class="tag">WEEK ${w.week} · 50 MCQs</span><h2>${esc(w.name)}</h2><p>${esc(w.description)}</p><p class="muted">25 code traces · 25 concepts · ${n}/50 attempted</p><div class="actions"><button class="primary" data-half-start="${w.week}" data-half-sample="yes">10 random questions →</button><button class="secondary" data-half-start="${w.week}">Complete week</button><button class="text-button" data-half-browse="${w.week}">Browse questions ↓</button></div><a class="text-button" href="#materials">Weekly slides and notes →</a></section>`;}).join('')}</div><section class="half-browser" aria-labelledby="half-browser-title"><div class="section-heading"><div><h2 id="half-browser-title" tabindex="-1">Find a question</h2><p>Search by idea, code, week or question ID.</p></div><span id="half-count" class="muted" role="status"></span></div><div class="program-toolbar"><label class="search"><input id="half-search" type="search" value="${esc(halfSearch)}" placeholder="Search second-half questions…" aria-label="Search second-half questions"></label><label class="topic-select">Week <select id="half-week"><option value="all">All weeks</option>${SECOND_HALF_WEEKS.map(w=>`<option value="${w.week}" ${halfWeek===String(w.week)?'selected':''}>Week ${w.week}</option>`).join('')}</select></label><label class="topic-select">Type <select id="half-mode">${[['all','All types'],['python-output','Code trace'],['concept','Concept']].map(([v,n])=>`<option value="${v}" ${v===halfMode?'selected':''}>${n}</option>`).join('')}</select></label><label class="topic-select">Progress <select id="half-progress">${[['all','All progress'],['new','Not attempted'],['missed','Revisit'],['correct','Correct']].map(([v,n])=>`<option value="${v}" ${v===halfProgress?'selected':''}>${n}</option>`).join('')}</select></label><button class="text-button" data-half-clear="yes">Clear filters</button></div><div class="exercise-grid" id="half-list"></div><div id="half-pagination"></div></section><p class="code-info">Weekly alignment: supplied Week 7–14 lecture notes and their reading companions. These newly authored questions are separate from the earlier Mock A–D collection. Earlier progress is retained.</p>`,'second-half');renderHalfList();}
function startHalf(value,short){let qs,label;if(value==='mixed'){qs=SECOND_HALF_WEEKS.flatMap(w=>sample(SECOND_HALF_MCQS.filter(q=>q.week===w.week),3));qs=sample(qs,qs.length);label='Weeks 7–14 · Mixed practice';}else if(value==='missed'){qs=SECOND_HALF_MCQS.filter(q=>state.records[q.id]&&!state.records[q.id].latestCorrect);label='Weeks 7–14 · Revisit';}else{qs=SECOND_HALF_MCQS.filter(q=>q.week===Number(value));if(short)qs=sample(qs,10);label='Week '+value+' · '+SECOND_HALF_WEEKS.find(w=>w.week===Number(value)).name;}if(!qs.length){document.getElementById('half-count').textContent='No missed second-half questions to revisit yet.';return;}startQuiz(qs.map(q=>q.id),label,'banks/weeks-7-14');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.halfStart)startHalf(b.dataset.halfStart,!!b.dataset.halfSample);else if(b.dataset.halfQuestion)startQuiz([b.dataset.halfQuestion],'Week '+SECOND_HALF_MCQS.find(q=>q.id===b.dataset.halfQuestion).week+' · Selected question');else if(b.dataset.halfPage!==undefined){halfPage=Number(b.dataset.halfPage);renderHalfList();}else if(b.dataset.halfBrowse){halfWeek=b.dataset.halfBrowse;halfMode='all';halfProgress='all';halfSearch='';halfPage=0;secondHalfHome();document.getElementById('half-browser-title').focus?.();document.getElementById('half-browser-title').scrollIntoView?.({behavior:'smooth'});}else if(b.dataset.halfClear){halfWeek=halfMode=halfProgress='all';halfSearch='';halfPage=0;secondHalfHome();}});
document.addEventListener('input',e=>{if(e.target.id==='half-search'){halfSearch=e.target.value;halfPage=0;renderHalfList();}});
document.addEventListener('change',e=>{if(e.target.id==='half-week')halfWeek=e.target.value;else if(e.target.id==='half-mode')halfMode=e.target.value;else if(e.target.id==='half-progress')halfProgress=e.target.value;else return;halfPage=0;renderHalfList();});
